import React, { useState, useEffect } from 'react';
import { Card, Button, Form, Table } from 'react-bootstrap';
import { Bar } from 'react-chartjs-2';
import axios from 'axios';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend
} from 'chart.js';

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

const API_URL = 'http://localhost:5000/api';

function Scheduler() {
  const [algorithm, setAlgorithm] = useState('fcfs');
  const [processes, setProcesses] = useState([]);
  const [ganttData, setGanttData] = useState([]);
  const [stats, setStats] = useState({});

  const [newProcess, setNewProcess] = useState({
    name: '',
    arrival_time: '',
    burst_time: '',
    priority: ''
  });

  useEffect(() => {
    fetchProcesses();
  }, []);

  const fetchProcesses = async () => {
    try {
      const response = await axios.get(`${API_URL}/scheduler/processes`);
      setProcesses(response.data);
    } catch (error) {
      console.error('Error fetching processes:', error);
    }
  };

  const addProcess = async () => {
    if (!newProcess.name || !newProcess.arrival_time || !newProcess.burst_time || !newProcess.priority) {
      alert('Please fill all fields');
      return;
    }
    
    try {
      await axios.post(`${API_URL}/scheduler/processes`, {
        ...newProcess,
        arrival_time: parseInt(newProcess.arrival_time),
        burst_time: parseInt(newProcess.burst_time),
        priority: parseInt(newProcess.priority)
      });
      fetchProcesses();
      setNewProcess({ name: '', arrival_time: '', burst_time: '', priority: '' });
    } catch (error) {
      console.error('Error adding process:', error);
    }
  };

  const runScheduler = async () => {
    try {
      const response = await axios.post(`${API_URL}/scheduler/run`, { algorithm });
      setGanttData(response.data.gantt_chart);
      setStats(response.data.statistics);
    } catch (error) {
      console.error('Error running scheduler:', error);
    }
  };

  const ganttChartData = {
    labels: ganttData.map(entry => `P${entry.pid}`),
    datasets: [{
      label: 'Execution Time',
      data: ganttData.map(entry => entry.end_time - entry.start_time),
      backgroundColor: [
        'rgba(255, 99, 132, 0.6)',
        'rgba(54, 162, 235, 0.6)',
        'rgba(255, 206, 86, 0.6)',
        'rgba(75, 192, 192, 0.6)',
        'rgba(153, 102, 255, 0.6)',
      ]
    }]
  };

  return (
    <div style={{ 
      display: 'flex', 
      height: '100%', 
      overflow: 'hidden',
      backgroundColor: '#f8f9fa'
    }}>
      {/* LEFT SECTION - 40% - Add Process */}
      <div style={{ 
        width: '40%', 
        padding: '20px', 
        borderRight: '2px solid #dee2e6',
        overflowY: 'auto',
        backgroundColor: '#ffffff'
      }}>
        <h4 className="mb-4" style={{ color: '#343a40', borderBottom: '3px solid #667eea', paddingBottom: '10px' }}>
          Add New Process
        </h4>
        
        <Form>
          <Form.Group className="mb-3">
            <Form.Label><strong>Process Name</strong></Form.Label>
            <Form.Control
              type="text"
              value={newProcess.name}
              onChange={(e) => setNewProcess({...newProcess, name: e.target.value})}
              placeholder="e.g., P1, P2, P3..."
              style={{ borderRadius: 0 }}
            />
          </Form.Group>

          <Form.Group className="mb-3">
            <Form.Label><strong>Arrival Time</strong></Form.Label>
            <Form.Control
              type="number"
              value={newProcess.arrival_time}
              onChange={(e) => setNewProcess({...newProcess, arrival_time: e.target.value})}
              placeholder="Enter arrival time"
              style={{ borderRadius: 0 }}
            />
          </Form.Group>

          <Form.Group className="mb-3">
            <Form.Label><strong>Burst Time</strong></Form.Label>
            <Form.Control
              type="number"
              value={newProcess.burst_time}
              onChange={(e) => setNewProcess({...newProcess, burst_time: e.target.value})}
              placeholder="Enter burst time"
              style={{ borderRadius: 0 }}
            />
          </Form.Group>

          <Form.Group className="mb-3">
            <Form.Label><strong>Priority</strong></Form.Label>
            <Form.Control
              type="number"
              value={newProcess.priority}
              onChange={(e) => setNewProcess({...newProcess, priority: e.target.value})}
              placeholder="Enter priority (1=highest)"
              style={{ borderRadius: 0 }}
            />
          </Form.Group>

          <Button 
            onClick={addProcess} 
            style={{ 
              width: '100%', 
              backgroundColor: '#667eea', 
              border: 'none',
              borderRadius: 0,
              padding: '12px',
              fontSize: '16px',
              fontWeight: 'bold'
            }}
          >
            Add Process
          </Button>
        </Form>

        <hr style={{ margin: '30px 0', borderTop: '2px solid #dee2e6' }} />

        <h4 className="mb-3" style={{ color: '#343a40', borderBottom: '3px solid #667eea', paddingBottom: '10px' }}>
          Scheduling Algorithm
        </h4>
        
        <Form.Group className="mb-3">
          <Form.Label><strong>Select Algorithm</strong></Form.Label>
          <Form.Select 
            value={algorithm} 
            onChange={(e) => setAlgorithm(e.target.value)}
            style={{ borderRadius: 0 }}
          >
            <option value="fcfs">First Come First Serve (FCFS)</option>
            <option value="sjf">Shortest Job First (SJF)</option>
            <option value="srtf">Shortest Remaining Time First (SRTF)</option>
            <option value="rr">Round Robin (RR)</option>
            <option value="priority">Priority Scheduling</option>
          </Form.Select>
        </Form.Group>

        <Button 
          onClick={runScheduler} 
          disabled={processes.length === 0}
          style={{ 
            width: '100%', 
            backgroundColor: '#28a745', 
            border: 'none',
            borderRadius: 0,
            padding: '12px',
            fontSize: '16px',
            fontWeight: 'bold'
          }}
        >
          Run Scheduler
        </Button>
      </div>

      {/* MIDDLE SECTION - 20% - Process List */}
      <div style={{ 
        width: '20%', 
        padding: '20px', 
        borderRight: '2px solid #dee2e6',
        overflowY: 'auto',
        backgroundColor: '#f8f9fa'
      }}>
        <h4 className="mb-4" style={{ color: '#343a40', borderBottom: '3px solid #667eea', paddingBottom: '10px' }}>
          Process Queue
        </h4>
        
        <div style={{ fontSize: '14px', marginBottom: '15px', color: '#6c757d' }}>
          Total: <strong>{processes.length}</strong> process(es)
        </div>

        {processes.length === 0 ? (
          <div style={{ 
            textAlign: 'center', 
            padding: '40px 20px', 
            color: '#6c757d',
            fontStyle: 'italic'
          }}>
            No processes added yet
          </div>
        ) : (
          <div>
            {processes.map((proc, index) => (
              <div 
                key={index} 
                style={{
                  backgroundColor: '#ffffff',
                  padding: '15px',
                  marginBottom: '10px',
                  border: '1px solid #dee2e6',
                  borderLeft: '4px solid #667eea',
                  borderRadius: 0
                }}
              >
                <div style={{ fontWeight: 'bold', fontSize: '16px', color: '#343a40', marginBottom: '8px' }}>
                  {proc.name}
                </div>
                <div style={{ fontSize: '12px', color: '#6c757d' }}>
                  <div>Arrival: <strong>{proc.arrival_time}</strong></div>
                  <div>Burst: <strong>{proc.burst_time}</strong></div>
                  <div>Priority: <strong>{proc.priority}</strong></div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* RIGHT SECTION - 40% - Stats and Gantt Chart */}
      <div style={{ 
        width: '40%', 
        display: 'flex',
        flexDirection: 'column',
        overflow: 'hidden'
      }}>
        {/* TOP HALF - Statistics */}
        <div style={{ 
          height: '50%', 
          padding: '20px', 
          borderBottom: '2px solid #dee2e6',
          overflowY: 'auto',
          backgroundColor: '#ffffff'
        }}>
          <h4 className="mb-4" style={{ color: '#343a40', borderBottom: '3px solid #667eea', paddingBottom: '10px' }}>
            Statistics
          </h4>
          
          {!stats.algorithm ? (
            <div style={{ 
              textAlign: 'center', 
              padding: '60px 20px', 
              color: '#6c757d',
              fontStyle: 'italic'
            }}>
              Run scheduler to see statistics
            </div>
          ) : (
            <div>
              <div style={{ 
                backgroundColor: '#667eea', 
                color: 'white', 
                padding: '20px', 
                marginBottom: '15px',
                borderRadius: 0
              }}>
                <div style={{ fontSize: '14px', opacity: 0.9 }}>Average Waiting Time</div>
                <div style={{ fontSize: '32px', fontWeight: 'bold' }}>
                  {stats.avg_waiting_time || '0'} ms
                </div>
              </div>

              <div style={{ 
                backgroundColor: '#f093fb', 
                color: 'white', 
                padding: '20px', 
                marginBottom: '15px',
                borderRadius: 0
              }}>
                <div style={{ fontSize: '14px', opacity: 0.9 }}>Average Turnaround Time</div>
                <div style={{ fontSize: '32px', fontWeight: 'bold' }}>
                  {stats.avg_turnaround_time || '0'} ms
                </div>
              </div>

              <div style={{ 
                backgroundColor: '#4facfe', 
                color: 'white', 
                padding: '20px',
                borderRadius: 0
              }}>
                <div style={{ fontSize: '14px', opacity: 0.9 }}>CPU Utilization</div>
                <div style={{ fontSize: '32px', fontWeight: 'bold' }}>
                  {stats.cpu_utilization || '0'}%
                </div>
              </div>
            </div>
          )}
        </div>

        {/* BOTTOM HALF - Gantt Chart */}
        <div style={{ 
          height: '50%', 
          padding: '20px', 
          overflowY: 'auto',
          backgroundColor: '#f8f9fa'
        }}>
          <h4 className="mb-4" style={{ color: '#343a40', borderBottom: '3px solid #667eea', paddingBottom: '10px' }}>
            Gantt Chart
          </h4>
          
          {ganttData.length === 0 ? (
            <div style={{ 
              textAlign: 'center', 
              padding: '60px 20px', 
              color: '#6c757d',
              fontStyle: 'italic'
            }}>
              Run scheduler to see Gantt chart
            </div>
          ) : (
            <div style={{ backgroundColor: '#ffffff', padding: '20px', borderRadius: 0 }}>
              <Bar 
                data={ganttChartData} 
                options={{
                  responsive: true,
                  maintainAspectRatio: false,
                  plugins: {
                    legend: {
                      display: false
                    }
                  }
                }}
                height={200}
              />
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default Scheduler;
